<script setup>
import {computed} from 'vue';
import {useClusterDashboard} from '../composables/useClusterDashboard';
import NativeTable from '../components/native/NativeTable.vue';
import NativePanel from '../components/native/NativePanel.vue';
const vm=useClusterDashboard();
const {S,data,selected,loading,error,canViewSales,racePeriod,raceMode,execBranch,execEmployee,execCategory,appointmentBranch,appointmentStaff,appointmentJourney,appointmentSearch,walkFrom,walkTo,walkBranch,comparisonLoading,collapsed,zoom,sections,money,period,sum,financialTotal,comparison,attendance,billingDues,recovery,recoveryTotals,recoveryEmployees,commitments,appointments,executions,executionEmployees,walk,walkEmployees,approvalRows,mediaRows,load,loadRace,compare,moveSection,exportSection}=vm;
const titles={conversions:'Branch Walk-in Conversions',race:'Sales Race Board',comparison:'Branch Comparison',attendance:'Branch-wise Absent Staff',dues:'Pending Dues & Recovery',appointments:'Walk-in Appointments by HO-CC',executions:'Appointments & Executions',media:'Media / Source Mix',approvals:'Approvals'};
const columns=(items)=>items.map(([k,l,t])=>({k,l,t}));
const comparisonColumns=columns([['code','Branch'],['cluster','Cluster'],['package','Package billed today','amt'],['today','Collections','amt'],['dues','Pending dues','amt'],['count','Invoices','int'],['fresh','New receipts','amt'],['recovery','Recovery receipts','amt'],['target','Target','amt'],['cycle','Sales month net','amt'],['last','Last month net','amt'],['rank','Rank','int']]);
const appointmentColumns=columns([['branch','Branch'],['client','Client'],['date','Appointment'],['agent','HO-CC Owner'],['consultant','Consultant'],['st','Status'],['journey','Journey'],['phone','Mobile'],['details','Client details'],['remarks','Remarks'],['firstVisit','First visit']]);
const raceRows=computed(()=>raceMode.value==='cluster'?S.race?.clusters||[]:S.race?.branches||[]);
const cards=computed(()=>[['Cluster net sale · ex-GST',money(financialTotal('cycle')),'comparison'],['Today collections',money(financialTotal('today')),'comparison'],['Staff present',sum('present')==null?'—':sum('present')+' / '+sum('staff'),'attendance'],['Pending dues',money(sum('dues')),'dues'],['Walks / Booked',S.walkSummary?S.walkSummary.walks+' / '+S.walkSummary.booked:'—','conversions'],['Overdue dues',money(sum('overdue')),'dues']]);
const walkBranches=computed(()=>S.cluster?.branches.map(([branch,code])=>({branch,code,...data.walkStats(walkFrom.value||period.value.from,walkTo.value||period.value.today,branch)}))||[]);
const dateString=value=>new Date(value||Date.now()).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'});
function toggle(id){collapsed.has(id)?collapsed.delete(id):collapsed.add(id);}
function jump(id){collapsed.delete(id);document.getElementById('cl-'+id)?.scrollIntoView({behavior:'smooth',block:'start'});}
const print=()=>window.print();
</script>
<template><section class="cluster-dashboard-page"><div id="clusterApp">
<header class="cl-header"><div class="cl-brand"><div><small>LIFE · CLUSTER OPERATIONS</small><h1>Cluster Command Center</h1><p>{{S.cluster?.name||'Cluster Dashboard'}} · {{period.from}} → {{period.to}}</p></div></div><nav><label>Cluster<select id="cl-select" v-model="selected" :disabled="loading||S.clusters.length===1" @change="load"><option v-for="cluster in S.clusters" :key="cluster.id" :value="cluster.id">{{cluster.name}} · {{cluster.branches.map(b=>b[1]).join(', ')}}</option></select></label><button id="cl-refresh" :disabled="loading" @click="load">{{loading?'Refreshing…':'Refresh'}}</button><button @click="print">Print</button></nav></header>
<p v-if="error" class="cl-error" role="alert">{{error}} <button @click="vm.initialize">Retry</button></p><p id="cl-status" role="status">{{loading?'Loading permitted cluster sources…':S.last?'Updated '+dateString(S.last):'Connecting…'}} <span v-if="Object.keys(S.errors).length">· Some sources unavailable; their totals are withheld.</span></p>
<div class="cl-kpis"><article><small>Today collections</small><strong id="cl-today">{{money(financialTotal('today'))}}</strong></article><article><small>Invoices today</small><strong id="cl-bills">{{sum('bills')??'—'}}</strong></article><article><small>Sales month</small><strong id="cl-month">{{money(financialTotal('cycle'))}}</strong></article><article><small>Staff</small><strong id="cl-att">P {{sum('present')??'—'}} · A {{sum('absent')??'—'}}</strong></article></div>
<div class="cl-ticker"><span v-for="(person,i) in S.ranking" :key="person.branch+'|'+person.name">{{i===0?'🥇':i===1?'🥈':'✦'}} {{person.name}} · {{person.branch}} · {{money(person.sale)}}</span></div>
<nav class="cl-nav"><button v-for="id in sections" :key="id" @click="jump(id)">{{titles[id]}}</button></nav>
<div class="cl-cards" id="cl-cards"><button v-for="[label,value,target] in cards" :key="label" class="cl-card" @click="jump(target)"><small>{{label}}</small><strong>{{value}}</strong></button></div>
<main id="cl-overview" class="cl-overview"><NativePanel v-for="id in sections" :id="'cl-'+id" :key="id" :title="titles[id]" :collapsed="collapsed.has(id)" :zoom="zoom===id" @toggle="toggle(id)" @zoom="zoom=zoom===id?'':id" @move="moveSection(id,$event)">
<template v-if="id==='conversions'"><div class="filters"><label>From<input v-model="walkFrom" type="date"></label><label>To<input v-model="walkTo" type="date"></label><select v-model="walkBranch"><option value="">All cluster branches</option><option v-for="[branch] in S.cluster?.branches||[]" :key="branch">{{branch}}</option></select></div><p v-if="S.errors.walkins" role="alert">{{S.errors.walkins}}</p><div class="cl-summary"><article><small>Visited clients</small><strong>{{S.walkRaw?walk.walks:'—'}}</strong></article><article><small>Booked</small><strong>{{S.walkRaw?walk.booked:'—'}}</strong></article><article><small>Conversion</small><strong>{{S.walkRaw?(walk.walks?Math.round(walk.booked/walk.walks*100):0)+'%':'—'}}</strong></article><article><small>Call Center / Direct / Referral</small><strong>{{S.walkRaw?[walk.cc,walk.direct,walk.referral].join(' / '):'—'}}</strong></article></div><NativeTable :rows="walkBranches" :columns="columns([['code','Branch'],['walks','Walks','int'],['booked','Booked','int'],['cc','Call Center','int'],['direct','Direct','int'],['referral','Referral','int']])"/><h3>Employee conversions</h3><NativeTable :rows="walkEmployees" :columns="columns([['name','Employee'],['walks','Walks','int'],['booked','Booked','int'],['ratio','Conversion','pct']])"/></template>
<template v-else-if="id==='race'"><div class="filters"><select v-model="racePeriod" @change="loadRace"><option value="today">Today</option><option value="cycle">Sales month</option></select><button @click="raceMode='cluster'">Cluster race · target achievement</button><button @click="raceMode='branch'">Branch ranking · net collections</button><button @click="loadRace">Refresh race</button></div><p v-if="S.errors.race" role="alert">{{S.errors.race}}</p><div class="race-lanes"><article v-for="(row,i) in raceRows" :key="row.id||row.code" class="race-lane"><b>#{{i+1}} {{row.name}}</b><span>{{row.achievement==null?'Target unavailable':row.achievement.toFixed(1)+'% achieved'}}</span><span v-if="canViewSales">{{money(row.net)}} / {{money(row.target)}}</span><progress :value="row.achievement||0" max="100"/><small>{{row.bills}} bills · {{row.fresh}} new clients · {{row.existing}} existing{{row.top?' · Top: '+row.top:''}}</small></article></div><h3>High Ticket Sale · top 6 employees</h3><NativeTable :rows="S.race?.high||[]" :columns="canViewSales?columns([['names','Employee(s)'],['branch','Branch'],['invoice','Invoice'],['date','Receipt date'],['net','Collected net','amt']]):columns([['names','Employee(s)'],['branch','Branch'],['invoice','Invoice'],['date','Receipt date']])"/><h3>Latest invoice-linked receipts</h3><NativeTable :rows="S.race?.latest||[]" :columns="canViewSales?columns([['name','Invoice'],['branch','Branch'],['date','Receipt date'],['net','Net collected','amt']]):columns([['name','Invoice'],['branch','Branch'],['date','Receipt date']])"/></template>
<template v-else-if="id==='comparison'"><div class="filters"><select v-model="S.compareMode"><option value="today">Today</option><option value="yesterday">Yesterday</option><option value="range">Custom range</option></select><template v-if="S.compareMode==='range'"><input v-model="S.compareFrom" type="date" aria-label="Comparison from"><input v-model="S.compareTo" type="date" aria-label="Comparison to"></template><button :disabled="comparisonLoading" @click="compare">Apply</button><button @click="exportSection('Comparison',comparison,comparisonColumns)">Export</button></div><p v-if="S.errors.comparison" role="alert">{{S.errors.comparison}}</p><NativeTable :rows="comparison" :columns="comparisonColumns"/><p>Collections include receipt-date recoveries. Financial values are ex-GST. Month is the 6th–5th cycle; rank uses current-cycle net sales.</p></template>
<template v-else-if="id==='attendance'"><p v-if="S.errors.attendance" role="alert">{{S.errors.attendance}}</p><NativeTable :rows="attendance" :columns="columns([['branch','Branch'],['employee_name','Employee'],['designation','Designation'],['today','Today'],['presentDays','Month present','int'],['absentDays','Month absent','int'],['halfDays','Month half-days','int']])" :total="false"/><p>Today’s absence is provisional. Punches, recorded attendance, weekly offs and approved leave are checked separately. Missing historical records are not counted as absences.</p></template>
<template v-else-if="id==='dues'"><h3>Billing pending dues</h3><p v-if="S.dues===null">Billing source unavailable or loading. Totals are withheld.</p><NativeTable :rows="billingDues" :columns="columns([['branch','Branch'],['client','Client / Invoice'],['invoiceList','Invoices'],['amount','Outstanding','amt'],['overdue','Overdue','amt'],['dueDates','Due dates']])"/><h3>Recovery sheet</h3><p v-if="S.errors.recovery" role="alert">{{S.errors.recovery}}</p><div class="cl-summary"><article v-for="[key,label] in [['real','Net pending'],['collected','Collected updates'],['committed','Confirmed commitments'],['writeoff','Not collectable']]" :key="key"><small>{{label}}</small><strong>{{money(recoveryTotals?.[key])}}</strong></article></div><NativeTable :rows="recovery" :columns="columns([['branch','Branch'],['count','Loaded invoices','int'],['expected','Expected','int'],['complete','Complete'],['gross','ERP dues','amt'],['collected','Collected updates','amt'],['committed','Confirmed','amt'],['writeoff','Not collectable','amt'],['real','Net pending','amt']])"/><h3>Commitments</h3><NativeTable :rows="commitments" :columns="columns([['label','Period'],['scheduled','Scheduled','amt'],['confirmed','Confirmed','amt']])"/><details><summary>Employee-wise recovery</summary><NativeTable :rows="recoveryEmployees" :columns="columns([['name','Branch / Owner'],['count','Invoices','int'],['gross','ERP dues','amt'],['collected','Collected','amt'],['committed','Confirmed','amt'],['real','Net pending','amt']])"/></details><p>Net pending = ERP dues − collected updates − not collectable. Commitments are not receipts. Scheduled and confirmed amounts overlap. Cluster totals are withheld when any recovery source is partial.</p></template>
<template v-else-if="id==='appointments'"><div class="filters"><input v-model="appointmentSearch" type="search" placeholder="Client, owner, branch, status"><select v-model="appointmentBranch"><option value="">All branches</option><option v-for="[branch] in S.cluster?.branches||[]" :key="branch">{{branch}}</option></select><select v-model="appointmentStaff"><option value="">All consultants</option><option v-for="name in [...new Set(S.appointments.map(w=>w.staff||'Unassigned'))]" :key="name">{{name}}</option></select><select v-model="appointmentJourney"><option value="">All journeys</option><option value="first">First visit</option><option value="repeat">Repeat visit</option><option value="visited">Visited</option><option value="pending">Not yet visited</option></select><button @click="exportSection('Appointments',appointments,appointmentColumns)">Export filtered</button></div><p>{{S.apNote||'Loading appointments…'}}</p><p v-if="S.errors.appointments" role="alert">{{S.errors.appointments}}</p><NativeTable :rows="appointments" :columns="appointmentColumns" :total="false"/></template>
<template v-else-if="id==='executions'"><div class="filters"><select v-model="execBranch"><option value="">All branches</option><option v-for="[b] in S.cluster?.branches||[]" :key="b">{{b}}</option></select><select v-model="execEmployee"><option value="">All employees</option><option v-for="e in [...new Set((S.execData?.sessions||[]).map(s=>s.owner))]" :key="e">{{e}}</option></select><select v-model="execCategory"><option value="">All services</option><option v-for="c in [...new Set((S.execData?.sessions||[]).map(s=>s.category))]" :key="c">{{c}}</option></select></div><p v-if="S.errors.executions" role="alert">{{S.errors.executions}}</p><NativeTable :rows="executions" :columns="columns([['code','Branch'],['appointments','Today appointments','int'],['visited','Visited / executed','int'],['today','Today executions','int'],['month','This sales month','int'],['last','Last sales month','int']])"/><h3>Employee-wise submitted sessions</h3><NativeTable :rows="executionEmployees" :columns="columns([['category','Service'],['branch','Branch'],['employee','Employee / Practitioner'],['today','Today','int'],['month','This sales month','int'],['last','Last sales month','int']])"/><p>Execution counts use submitted Therapy Sessions by creation date. Service appointments remain branch totals.</p></template>
<template v-else-if="id==='media'"><p v-if="S.errors.media" role="alert">{{S.errors.media}}</p><NativeTable :rows="mediaRows" :columns="columns([['m','Source'],['c','Plans','int'],['inv_count','Invoices','int'],['billed','Billed net','amt'],['collected','Collected net','amt'],['share','Share','pct']])"/><p>Collections follow receipt dates; billing follows invoice dates.</p></template>
<template v-else><p v-if="S.errors.approvals" role="alert">{{S.errors.approvals}}</p><NativeTable :rows="approvalRows" :columns="columns([['code','Branch'],['discount','Discount pending','int'],['p2p','P2P pending','int'],['c2c','C2C pending','int'],['b2b','B2B pending','int'],['requested','Stock requested','int'],['approved','Stock approved','int'],['sent','Stock sent','int']])"/><p>Approval and stock statuses are independent. Missing sources are shown as unavailable.</p></template>
</NativePanel></main></div></section></template>
<style scoped src="../styles/cluster-dashboard.css"></style>
<style scoped>.cluster-dashboard-page{background:#f3f7f3;padding:18px;color:#163c2c;font:14px system-ui;min-width:0}.cl-header{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;padding:20px;background:#144c37;color:white;border-radius:14px}.cl-header h1{font-size:25px;margin:4px 0}.cl-header nav,.filters,.cl-nav{display:flex;gap:8px;flex-wrap:wrap;align-items:center}button,input,select{font:inherit;padding:8px 10px;border:1px solid #c5d9cc;border-radius:6px}button{background:white;color:#174d34;cursor:pointer}button:disabled{opacity:.6}.cl-kpis,.cl-cards,.cl-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:16px 0}.cl-kpis article,.cl-card,.cl-summary article{background:white;padding:16px;border:1px solid #d4e4d9;border-radius:12px;text-align:left}.cl-kpis strong,.cl-card strong,.cl-summary strong{display:block;font-size:24px;margin-top:6px}.cl-ticker{display:flex;gap:24px;overflow:auto;padding:12px;color:#856013;background:#fff7d9}.cl-ticker span{white-space:nowrap}.cl-nav{padding:14px 0}.cl-overview{display:grid;gap:18px}.filters{margin-bottom:14px}.filters label{display:grid;gap:4px}.cl-error{color:#a52d25}.race-lanes{display:grid;gap:12px}.race-lane{display:flex;gap:12px;flex-wrap:wrap;align-items:center;padding:14px;border:1px solid #d7dfca;border-radius:10px;background:#fffcec}.race-lane progress{width:100%;height:20px;accent-color:#c5a030}.race-lane small{width:100%}h3{margin:18px 0 10px;font-size:17px}@media print{.cl-header nav,.cl-nav,.filters{display:none}}</style>
